hudson.tasks.BatchFile.command:
:: -----------------------------------------------
:: PRE-BUILD CLEANUP - Remove existing .Z and .specification files
:: -----------------------------------------------
echo Cleaning up existing output files from workspace...

if exist "%WORKSPACE%\*.Z" (
    del /Q /F "%WORKSPACE%\*.Z"
    echo Deleted old .Z files.
)

if exist "%WORKSPACE%\*.specification" (
    del /Q /F "%WORKSPACE%\*.specification"
    echo Deleted old .specification files.
)
set MACRO_JAR=%WORKSPACE%\src\main\resources\macro_FILE_G5_V1.jar
if exist "%MACRO_JAR%" (
    del /F /Q "%MACRO_JAR%"
    echo Deleted macro JAR from resources: %MACRO_JAR%
) else (
    echo Macro JAR not found in resources, skipping: %MACRO_JAR%
)

:: Delete macro_FILE_G5_V1.jar from builds folder
set JAR_TO_DELETE=%WORKSPACE%\macro_FILE_G5_V1.jar
if exist "%JAR_TO_DELETE%" (
    del /F /Q "%JAR_TO_DELETE%"
    echo Deleted: %JAR_TO_DELETE%
) else (
    echo File not found, skipping: %JAR_TO_DELETE%
)
